patch.content:
/* Shop.mn-ийн загвар */

body {
  background-color: #f5f6f8;
  color: #18181b;
}

body {
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
}

h1 {
  font-size: 36px;
}

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.product-grid {
  /* Mobile-first: утсан дээр нэг багана */
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
}

/* энд бичнэ үү */
